// SPDX-License-Identifier: AGPL-3.0-or-later

pragma solidity ^0.8.0;

import "../../exchange/contracts/periphery/contracts/access-control/Pausable.sol";
import "../../exchange/contracts/periphery/contracts/access-control/SuAuthenticated.sol";
import "../../exchange/contracts/periphery/contracts/adapters/UniswapV3Adapter.sol";
import "../interfaces/IUniswapV3NFTWrapper.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol";

contract UniswapV3NFTWrapper is ERC20Upgradeable, Pausable, ERC721Holder, IUniswapV3NFTWrapper {
    using SafeERC20 for IERC20;

    UniswapV3Adapter public adapter; // UniswapV3Adapter address
    IUniswapV3PositionManager public positionManager; // UniswapV3 position manager address

    struct PositionInfo {
        uint256 tokenId;
        uint256 wrapperAmount;
        address safeHandler;
        address owner;
        address ownerProxy;
    }

    mapping(uint256 => PositionInfo) public positions; // tokenId => PositionInfo
    mapping(address => uint256[]) public userPositions; // user => tokenIds

    modifier onlyPositionOwnerOrProxy(uint256 tokenId, address owner) {
        // check if position exists first
        require(positions[tokenId].tokenId != 0, "UniswapV3Wrapper/no-deposited");
        // if caller is not the same as owner, caller should be dssProxyActions
        if (msg.sender != owner) {
            require(msg.sender == positions[tokenId].ownerProxy, "UniswapV3Wrapper/not-owner");
        }
        // check if owner is the correct owner of position
        require(positions[tokenId].owner == owner, "UniswapV3Wrapper/not-stored-owner");
        _;
    }

    function initialize(address accessControl_, address adapter_) public initializer {
        __ERC20_init("StableUnit LP Wrapper", "suLP");
        __suAuthenticatedInit(accessControl_); // Set up role-based access control
        adapter = UniswapV3Adapter(adapter_);
        positionManager = adapter.positionManager();
    }

    // Prevents initialization of the implementation contract for upgradeability safety
    // StableUnit addition: Ensures the contract cannot be initialized outside of proxy deployment
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // Deposits NFT Position
    // Transfers the NFT Position from msg.sender to this contract and calculates the value of the position
    // Mints wrapper tokens to the caller and updates positions
    // @param tokenId NFT Position tokenId
    // @param safeHandler Safe handler from dssCdpManager for owner
    function depositNFT(uint256 tokenId, address safeHandler) external returns (uint256) {
        return depositNFTFor(tokenId, msg.sender, safeHandler);
    }

    // Deposits NFT Position for receiver
    // Transfers the NFT Position from msg.sender to this contract and calculates the value of the position
    // Mints wrapper tokens to the caller and updates positions
    // @param tokenId NFT Position tokenId
    // @param receiver Position owner address
    // @param safeHandler Safe handler from dssCdpManager for owner
    function depositNFTFor(uint256 tokenId, address receiver, address safeHandler) public returns (uint256) {
        PositionInfo storage position = positions[tokenId];
        // Transfers the NFT Position to this contract
        positionManager.safeTransferFrom(msg.sender, address(this), tokenId);
        // Calculates the value in usd of the position
        uint256 price = adapter.getFiatPrice1e18(tokenId);
        require(price != 0, "UniswapV3Wrapper/invalid-price");
        // Mints wrapper tokens
        _mint(msg.sender, price);

        // Updates storage
        position.tokenId = tokenId;
        position.wrapperAmount = price;
        position.safeHandler = safeHandler;
        position.owner = receiver;
        position.ownerProxy = msg.sender;

        userPositions[safeHandler].push(tokenId);

        emit DepositNFT(tokenId, price);
        return price;
    }

    // Withdraws NFT Position
    // Burns wrapper tokens
    // Decreases full liquidity from the position manager and collects underlying tokens
    // Transfers underlying tokens to the caller
    // @param tokenId NFT Position tokenId
    // @return token0 Address of the first underlying token
    // @return token1 Address of the second underlying token
    // @return amount0 Amount of first token received
    // @return amount1 Amount of second token received
    function withdrawNFT(uint256 tokenId, address owner) public returns(address, address, uint256, uint256) {
        return _withdrawPartial(tokenId, positions[tokenId].wrapperAmount, owner, false);
    }

    // Withdraws NFT Position partially
    // Burns wrapper tokens
    // Calculates the liquidity amount to burn and decreases the liquidity from the position manager
    // Collects underlying tokens and transfers them to the caller
    // @param tokenId NFT Position tokenId
    // @param wrapperAmount wrapper token amount to burn
    function withdrawPartial(
        uint256 tokenId,
        uint256 wrapperAmount,
        address owner
    ) public onlyPositionOwnerOrProxy(tokenId, owner) whenNotPaused returns (address, address, uint256, uint256) {
        return _withdrawPartial(tokenId, wrapperAmount, owner, false);
    }

    function _withdrawPartial(
        uint256 tokenId,
        uint256 wrapperAmount,
        address owner,
        bool keepInContract
    ) internal returns (address, address, uint256, uint256) {
        require(positions[tokenId].wrapperAmount >= wrapperAmount, "UniswapV3Wrapper/invalid-wrapperAmount");

        PositionInfo memory position = positions[tokenId];
        if (position.wrapperAmount == wrapperAmount) {
            _removePosition(tokenId, position.safeHandler);
        } else {
            positions[tokenId].wrapperAmount = position.wrapperAmount - wrapperAmount;
        }

        _burn(owner, wrapperAmount);

        (, , address token0, address token1, , , , uint128 liquidity, , , , ) = positionManager.positions(tokenId);
        require(liquidity != 0, "UniswapV3Wrapper/insufficient-liquidity");

        // Withdraw liquidity
        (uint256 amount0, uint256 amount1) = _performWithdraw(
            tokenId,
            uint128((uint256(liquidity) * wrapperAmount) / position.wrapperAmount),
            token0,
            token1
        );

        if (!keepInContract) {
            IERC20(token0).safeTransfer(owner, amount0);
            IERC20(token1).safeTransfer(owner, amount1);
        }

        emit WithdrawNFT(tokenId, wrapperAmount);

        return (token0, token1, amount0, amount1);
    }

    function _removePosition(uint256 tokenId, address safeHandler) internal {
        delete positions[tokenId];
        uint256 userCount = userPositions[safeHandler].length;
        for (uint256 i; i < userCount; i++) {
            if (tokenId == userPositions[safeHandler][i]) {
                userPositions[safeHandler][i] = userPositions[safeHandler][userCount - 1];
                userPositions[safeHandler].pop();
                break;
            }
        }
    }

    function _performWithdraw(
        uint256 tokenId,
        uint128 liquidityToBurn,
        address token0,
        address token1
    ) internal returns (uint256 amount0, uint256 amount1) {
        uint256 balanceBefore0 = IERC20(token0).balanceOf(address(this));
        uint256 balanceBefore1 = IERC20(token1).balanceOf(address(this));

        _withdrawUnderlying(tokenId, liquidityToBurn);

        amount0 = IERC20(token0).balanceOf(address(this)) - balanceBefore0;
        amount1 = IERC20(token1).balanceOf(address(this)) - balanceBefore1;
    }

    function emergencyWithdraw(
        address[] calldata tokens,
        uint256[] calldata amounts,
        address receiver
    ) external onlyAdmin {
        for (uint256 i; i < tokens.length; i++) {
            IERC20(tokens[i]).safeTransfer(receiver, amounts[i]);
        }

        emit EmergencyWithdrawNFT(tokens, amounts, receiver);
    }

    function _withdrawUnderlying(uint256 tokenId, uint128 liquidity) internal {
        // TODO slippage check
        // Need to require users to input max slippage bps or set a max slippage bps in storage
        // Pre-calculate withdrawable amounts of underlying tokens when withdrawing the liquidity and
        // get expected amounts based on max bps
        // Compare actual received token amounts and expected amounts

        IUniswapV3PositionManager.DecreaseLiquidityParams memory params = IUniswapV3PositionManager
            .DecreaseLiquidityParams({
                tokenId: tokenId,
                liquidity: liquidity,
                amount0Min: 0,
                amount1Min: 0,
                deadline: block.timestamp
            });

        positionManager.decreaseLiquidity(params);

        positionManager.collect(
            IUniswapV3PositionManager.CollectParams({
                tokenId: tokenId,
                recipient: address(this),
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );
    }

    /**
     * @notice Get the total deposited value for a user across all their positions
     * @param safeHandler The address of the user
     * @return totalValue The total USD value of all user's positions
     */
    function getFiatPrice1e18(address safeHandler) external view returns (uint256 totalValue) {
        uint256[] memory userPositionIds = userPositions[safeHandler];
        totalValue = 0;

        for (uint256 i = 0; i < userPositionIds.length; i++) {
            totalValue += adapter.getFiatPrice1e18(userPositionIds[i]);
        }

        return totalValue;
    }

    /**
     * @notice Withdraws all NFT positions for a user
     * @dev Burns all wrapper tokens for the user and returns all underlying tokens
     *      This function aggregates tokens from multiple positions
     * @param user Address of the user whose positions to withdraw
     * @return tokens Array of WithdrawnToken structs containing unique token addresses and aggregated amounts
     */
    function withdrawAllUserNFT(address user) external whenNotPaused onlyCollateralAuctionAccess returns (WithdrawnToken[] memory tokens) {
        uint256[] memory tokenIds = userPositions[user];
        require(tokenIds.length > 0, "UniswapV3Wrapper/no-positions");

        // Use dynamic arrays to handle multiple different tokens
        // Max possible unique tokens = tokenIds.length * 2 (if all positions have different token pairs)
        address[] memory tokenAddresses = new address[](tokenIds.length * 2);
        uint256[] memory tokenAmounts = new uint256[](tokenIds.length * 2);
        uint256 uniqueTokenCount = 0;

        for (uint256 i = 0; i < tokenIds.length; i++) {
            uint256 tokenId = tokenIds[i];
            PositionInfo memory position = positions[tokenId];

            (address token0, address token1, uint256 amount0, uint256 amount1) = _withdrawPartial(
                tokenId,
                position.wrapperAmount,
                msg.sender, // CollateralAuctionHouse will have suLP to burn
                true
            );

            // Aggregate token0
            if (amount0 > 0) {
                bool found = false;
                for (uint256 j = 0; j < uniqueTokenCount; j++) {
                    if (tokenAddresses[j] == token0) {
                        tokenAmounts[j] += amount0;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    tokenAddresses[uniqueTokenCount] = token0;
                    tokenAmounts[uniqueTokenCount] = amount0;
                    uniqueTokenCount++;
                }
            }

            // Aggregate token1
            if (amount1 > 0) {
                bool found = false;
                for (uint256 j = 0; j < uniqueTokenCount; j++) {
                    if (tokenAddresses[j] == token1) {
                        tokenAmounts[j] += amount1;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    tokenAddresses[uniqueTokenCount] = token1;
                    tokenAmounts[uniqueTokenCount] = amount1;
                    uniqueTokenCount++;
                }
            }
        }

        // Create result array with exact size
        tokens = new WithdrawnToken[](uniqueTokenCount);
        for (uint256 i = 0; i < uniqueTokenCount; i++) {
            tokens[i] = WithdrawnToken({
                tokenAddress: tokenAddresses[i],
                tokenAmount: tokenAmounts[i]
            });

            // Transfer aggregated tokens to caller
            IERC20(tokenAddresses[i]).safeTransfer(msg.sender, tokenAmounts[i]);
        }

        return tokens;
    }
}

